import { useEffect, useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  fetchIntersections,
  fetchPrediction,
  fetchTraffic,
  fetchWeather,
} from "./api/client";
import "./App.css";

const APPROACH_OPTIONS = ["全部方向", "东向西", "西向东", "南向北", "北向南"];

function toApiTime(value) {
  if (!value) return undefined;
  return value.replace("T", " ");
}

function summarizeTraffic(records) {
  const grouped = new Map();
  records.forEach((item) => {
    const key = item.approach;
    const current = grouped.get(key) || { approach: key, vehicleCount: 0, speedTotal: 0, n: 0 };
    current.vehicleCount += item.vehicle_count;
    current.speedTotal += item.avg_speed;
    current.n += 1;
    grouped.set(key, current);
  });
  return [...grouped.values()].map((item) => ({
    approach: item.approach,
    vehicleCount: item.vehicleCount,
    avgSpeed: Number((item.speedTotal / item.n).toFixed(1)),
  }));
}

function projectPosition(intersections) {
  const withCoord = intersections.filter((item) => item.longitude !== 0 || item.latitude !== 0);
  if (!withCoord.length) return [];
  const lngs = withCoord.map((item) => item.longitude);
  const lats = withCoord.map((item) => item.latitude);
  const minLng = Math.min(...lngs);
  const maxLng = Math.max(...lngs);
  const minLat = Math.min(...lats);
  const maxLat = Math.max(...lats);
  const lngRange = maxLng - minLng || 1;
  const latRange = maxLat - minLat || 1;

  return withCoord.map((item) => ({
    ...item,
    x: ((item.longitude - minLng) / lngRange) * 100,
    y: 100 - ((item.latitude - minLat) / latRange) * 100,
  }));
}

function App() {
  const [intersections, setIntersections] = useState([]);
  const [selectedRoad, setSelectedRoad] = useState("");
  const [selectedDirection, setSelectedDirection] = useState("全部方向");
  const [timeRange, setTimeRange] = useState("");

  const [trafficRows, setTrafficRows] = useState([]);
  const [predictionRows, setPredictionRows] = useState([]);
  const [weather, setWeather] = useState(null);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    let active = true;
    async function bootstrap() {
      try {
        setError("");
        const data = await fetchIntersections();
        if (!active) return;
        setIntersections(data);
        if (data.length) {
          setSelectedRoad((prev) => prev || data[0].site_name);
        }
      } catch (err) {
        if (!active) return;
        setError(`加载路口失败：${err.message}`);
      }
    }
    bootstrap();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    if (!selectedRoad) return;
    let active = true;
    async function loadData() {
      try {
        setLoading(true);
        setError("");
        const params = {
          road_name: selectedRoad,
          time_range: toApiTime(timeRange),
          direction: selectedDirection === "全部方向" ? undefined : selectedDirection,
          limit: 500,
        };
        const [trafficData, weatherData, predictionData] = await Promise.all([
          fetchTraffic(params),
          fetchWeather({ time_range: params.time_range }),
          fetchPrediction({ road_name: selectedRoad, time_range: params.time_range }),
        ]);
        if (!active) return;
        setTrafficRows(trafficData);
        setWeather(weatherData);
        setPredictionRows(predictionData);
      } catch (err) {
        if (!active) return;
        setError(`数据请求失败：${err.message}`);
      } finally {
        if (active) setLoading(false);
      }
    }
    loadData();
    return () => {
      active = false;
    };
  }, [selectedRoad, selectedDirection, timeRange]);

  const summary = useMemo(() => summarizeTraffic(trafficRows), [trafficRows]);
  const points = useMemo(() => projectPosition(intersections), [intersections]);
  const selectedInfo = intersections.find((item) => item.site_name === selectedRoad);

  return (
    <div className="page">
      <header className="topbar">
        <div>
          <h1>交通流量监控系统</h1>
          <p>路口监控 · 数据分析 · 趋势预测</p>
        </div>
        <div className="filters">
          <select value={selectedRoad} onChange={(e) => setSelectedRoad(e.target.value)}>
            {intersections.map((item) => (
              <option key={item.site_name} value={item.site_name}>
                {item.site_name}
              </option>
            ))}
          </select>
          <select value={selectedDirection} onChange={(e) => setSelectedDirection(e.target.value)}>
            {APPROACH_OPTIONS.map((item) => (
              <option key={item} value={item}>
                {item}
              </option>
            ))}
          </select>
          <input
            type="datetime-local"
            value={timeRange}
            onChange={(e) => setTimeRange(e.target.value)}
          />
        </div>
      </header>

      {error ? <div className="alert">{error}</div> : null}

      <main className="layout">
        <section className="map-card">
          <h2>路口地图视图</h2>
          <div className="map-board">
            {points.map((point) => (
              <button
                key={point.site_name}
                type="button"
                className={`map-dot ${selectedRoad === point.site_name ? "active" : ""}`}
                style={{ left: `${point.x}%`, top: `${point.y}%` }}
                onClick={() => setSelectedRoad(point.site_name)}
                title={`${point.site_name} (${point.longitude}, ${point.latitude})`}
              >
                <span>{point.site_name}</span>
              </button>
            ))}
          </div>
          <div className="road-meta">
            <strong>{selectedRoad || "未选择路口"}</strong>
            <span>
              坐标：
              {selectedInfo
                ? `${selectedInfo.longitude.toFixed(6)}, ${selectedInfo.latitude.toFixed(6)}`
                : "-"}
            </span>
          </div>
        </section>

        <section className="right-panel">
          <article className="card weather">
            <h3>天气</h3>
            <p>{weather ? weather.weather : "-"}</p>
            <small>
              最高 {weather ? weather.tmax : "-"}°C · 最低 {weather ? weather.tmin : "-"}°C
            </small>
          </article>

          <article className="card">
            <h3>流量与车速（按方向聚合）</h3>
            <div className="chart">
              <ResponsiveContainer width="100%" height={260}>
                <BarChart data={summary}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="approach" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="vehicleCount" name="车流量" fill="#0b79d0" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </article>

          <article className="card">
            <h3>预测趋势</h3>
            <div className="chart">
              <ResponsiveContainer width="100%" height={220}>
                <LineChart data={predictionRows}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="timestamp" />
                  <YAxis />
                  <Tooltip />
                  <Line
                    type="monotone"
                    dataKey="predicted_vehicle_count"
                    name="预测车流量"
                    stroke="#e14e2d"
                    strokeWidth={2}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </article>
        </section>
      </main>

      {loading ? <div className="loading">数据更新中...</div> : null}
    </div>
  );
}

export default App;
